    @Test
    void corporateNeedsTheCodeOfACompanyWithAnAgreement() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(corporate(null))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(corporate("tecnosul"))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(corporate("OUTRA"))));

        Reservation reservation = service.create(corporate("TECNOSUL"));

        assertEquals(new BigDecimal("686.22"), reservation.price().total());
        assertEquals("TECNOSUL", service.find(reservation.id()).companyCode());
        service.confirm(reservation.id());
        assertEquals(new BigDecimal("686.22"), service.cancel(reservation.id()).refund());
    }

    @Test
    void weekendPackageOnlyFromFridayToSunday() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(
                stay(201, "2027-03-11", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(
                stay(201, "2027-03-12", "2027-03-15", 2, RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(
                stay(201, "2027-03-12", "2027-03-13", 2, RatePlan.WEEKEND_PACKAGE))));

        Reservation reservation = service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.WEEKEND_PACKAGE));
        service.confirm(reservation.id());

        assertEquals(new BigDecimal("820.00"), reservation.price().total());
        assertEquals(new BigDecimal("410.00"), service.cancel(reservation.id()).refund());
    }

    @Test
    void longStayNeedsSevenNights() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> service.create(
                stay(101, "2027-03-01", "2027-03-07", 2, RatePlan.LONG_STAY))));

        Reservation reservation = service.create(stay(101, "2027-03-01", "2027-03-08", 2, RatePlan.LONG_STAY));
        service.confirm(reservation.id());

        assertEquals(new BigDecimal("1574.37"), reservation.price().total());
        assertEquals(new BigDecimal("1574.37"), service.cancel(reservation.id()).refund());
    }
}
